"""D-Day and Dunkirk missions (both sides): data used by make_battle_missions.py (missions.json) and voice_battles.py (voices)."""

def S(af, ac, role, objs, brief, lines, protect=None, wing=None):
    return {"af": af, "ac": ac, "role": role, "objs": objs, "brief": brief, "lines": lines, "protect": protect, "wing": wing}


def L(s1, s2, first, half, all_, win, lose):
    return {"start_1": s1, "start_2": s2, "first": first, "half": half, "all": all_, "win": win, "lose": lose}


def D(s1, s2, loss1, loss2, win, lose):
    return {"start_1": s1, "start_2": s2, "loss_1": loss1, "loss_2": loss2, "win": win, "lose": lose}


def EV(kind, lat, lon, km, **kw):
    e = {"kind": kind, "lat": lat, "lon": lon, "trigger_km": km}
    e.update(kw)
    return e


